    /**
     * Method to retrieve the Timesheet via TimesheetFetchOneSummary
     * @param 	summary TimesheetFetchOneSummary 
     * @return 	TimesheetFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Timesheet getTimesheet( TimesheetFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "TimesheetFetchOneSummary arg cannot be null" );
    	
    	Timesheet entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Timesheet
        	// --------------------------------------
        	CompletableFuture<Timesheet> futureEntity = queryGateway.query(new FindTimesheetQuery( new LoadTimesheetFilter( summary.getTimesheetId() ) ), ResponseTypes.instanceOf(Timesheet.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Timesheet with id " + summary.getTimesheetId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


